import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

describe('email-incident-creation-flow: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test('email-incident-creation-flow: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_f9055f6ae4b54e90b6e87ba73d9bd436.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Verify imports
        expect(fluentContent).toContain('import {')
        expect(fluentContent).toContain('Flow')
        expect(fluentContent).toContain('action')
        expect(fluentContent).toContain('wfa')
        expect(fluentContent).toContain('trigger')

        // Flow definition
        expect(fluentContent).toContain('Flow(')
        expect(fluentContent).toContain("name: 'Email Incident/Task Creation Flow'")
        expect(fluentContent).toContain('Creates incidents or tasks based on email content')

        // Trigger: Inbound email
        expect(fluentContent).toContain('wfa.trigger(')
        expect(fluentContent).toContain('trigger.application.inboundEmail')
        expect(fluentContent).toContain('email_conditions:')
        expect(fluentContent).toContain('subjectLIKEraise incident or task')
        expect(fluentContent).toContain("target_table: 'incident'")

        // Action 1: Log email received
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Log inbound email received'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Email received from:')
        expect(fluentContent).toContain("wfa.dataPill(_params.trigger.from_address, 'string')")
        expect(fluentContent).toContain('Subject:')
        expect(fluentContent).toContain("wfa.dataPill(_params.trigger.subject, 'string')")

        // Action 2: lookUpRecord (sender by email)
        expect(fluentContent).toContain('action.core.lookUpRecord')
        expect(fluentContent).toContain("annotation: 'Retrieve sender user record'")
        expect(fluentContent).toContain("sort_type: 'sort_asc'")
        expect(fluentContent).toContain('conditions: `email=')
        expect(fluentContent).toContain("wfa.dataPill(_params.trigger.from_address, 'string')")
        expect(fluentContent).toContain("table: 'sys_user'")
        expect(fluentContent).toContain("if_multiple_records_are_found_action: 'use_first_record'")

        // If logic: Check internal sender and P1
        expect(fluentContent).toContain('wfa.flowLogic.if(')
        expect(fluentContent).toContain("annotation: 'Check if internal sender and P1 request'")
        expect(fluentContent).toMatch(/condition:\s*`\$\{wfa\.dataPill\([^)]+\.email,\s*'string'\)\}LIKEservicenow/)
        expect(fluentContent).toContain('LIKEP1')

        // Action 3: lookUpRecord (manager details)
        expect(fluentContent).toContain("annotation: 'Retrieve sender manager details'")
        expect(fluentContent).toContain("sort_type: 'sort_asc'")
        expect(fluentContent).toContain("if_multiple_records_are_found_action: 'use_first_record'")

        // Action 4: createTask (P1 task for manager)
        expect(fluentContent).toContain('action.core.createTask')
        expect(fluentContent).toContain("annotation: 'Create P1 task for sender manager'")
        expect(fluentContent).toContain("task_table: 'incident'")
        expect(fluentContent).toContain('field_values: TemplateValue(')
        expect(fluentContent).toContain("priority: '1'")
        expect(fluentContent).toContain("urgency: '1'")
        expect(fluentContent).toContain("impact: '1'")

        // Action 5: createTask (P1 task for sender)
        expect(fluentContent).toContain("annotation: 'Create P1 task for sender'")
        expect(fluentContent).toContain('field_values: TemplateValue(')

        // Action 6: sendNotification
        expect(fluentContent).toContain('action.core.sendNotification')
        expect(fluentContent).toContain("annotation: 'Send P1 task creation confirmation'")
        expect(fluentContent).toContain("notification: 'p1_tasks_created_notification'")

        // Else logic
        expect(fluentContent).toContain('wfa.flowLogic.else(')
        expect(fluentContent).toContain("annotation: 'Create P3 incident for non-P1 or external requests'")

        // Action: createRecord (P3 incident)
        expect(fluentContent).toContain("annotation: 'Create P3 incident from email'")
        expect(fluentContent).toContain('values: TemplateValue(')
        expect(fluentContent).toContain("priority: '4'")
        expect(fluentContent).toContain("urgency: '3'")
        expect(fluentContent).toContain("impact: '3'")
        expect(fluentContent).toContain("contact_type: 'email'")

        // Action: getAttachmentsOnRecord
        expect(fluentContent).toContain('action.core.getAttachmentsOnRecord')
        expect(fluentContent).toContain("annotation: 'Retrieve email attachments'")

        // forEach loop
        expect(fluentContent).toContain('wfa.flowLogic.forEach(')
        expect(fluentContent).toContain("annotation: 'Copy each attachment to incident'")

        // Action: copyAttachment
        expect(fluentContent).toContain('action.core.copyAttachment')
        expect(fluentContent).toContain("annotation: 'Copy attachment from email to incident'")

        // Action: sendEmail
        expect(fluentContent).toContain('action.core.sendEmail')
        expect(fluentContent).toContain("annotation: 'Send P3 incident creation confirmation'")
        expect(fluentContent).toContain('watermark_email: true')
        expect(fluentContent).toContain('ah_subject: `Incident Created:')

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)!.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        expect(mergedRecords['sys_hub_flow']).toBeDefined()
        expect(mergedRecords['sys_hub_action_instance_v2']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_logic_instance_v2']).toBeDefined()

        // Validate flow record
        const flows = mergedRecords['sys_hub_flow']
        const flow = flows.find((f: any) => f.name === 'Email Incident/Task Creation Flow')
        expect(flow).toBeDefined()
        expect(flow.type).toBe('flow')
        expect(flow.generation_source).toBe('fluent')

        // Validate trigger
        if (mergedRecords['sys_hub_trigger_instance_v2']) {
            const triggerInstances = mergedRecords['sys_hub_trigger_instance_v2']
            const trigger = triggerInstances.find((t: any) => t.flow === flow.sys_id)
            if (trigger) {
                expect(trigger.trigger_type).toBe('email')
                const triggerInputs = unzipInputArray(trigger.trigger_inputs)
                const triggerVar = (name: string) => findInput(triggerInputs, name)?.value
                expect(triggerVar('email_conditions')).toBe('subjectLIKEraise incident or task')
                expect(triggerVar('target_table')).toBe('incident')
            }
        }

        // Validate actions
        const actionInstances = mergedRecords['sys_hub_action_instance_v2']
        expect(actionInstances.length).toBeGreaterThanOrEqual(5)

        // Action 1: Log email received
        const logEmail = actionInstances.find((a: any) => a.comment?.includes('Log inbound email received'))
        expect(logEmail).toBeDefined()
        const logEmailValues = unzipInputArray(logEmail.values)
        const logEmailVar = (name: string) => findInput(logEmailValues, name)?.value
        expect(logEmailVar('log_level')).toBe('info')
        expect(logEmailVar('log_message')).toContain('Email received from')
        expect(logEmailVar('log_message')).toContain('from_address')
        expect(logEmailVar('log_message')).toContain('subject')

        // Action 2: lookUpRecord (sender)
        const lookupSender = actionInstances.find((a: any) => a.comment?.includes('Retrieve sender user record'))
        expect(lookupSender).toBeDefined()
        const lookupSenderValues = unzipInputArray(lookupSender.values)
        const lookupSenderVar = (name: string) => findInput(lookupSenderValues, name)?.value
        expect(lookupSenderVar('table')).toBe('sys_user')
        expect(lookupSenderVar('sort_type')).toBe('sort_asc')
        expect(lookupSenderVar('conditions')).toContain('email=')
        expect(lookupSenderVar('conditions')).toContain('from_address')
        expect(lookupSenderVar('if_multiple_records_are_found_action')).toBe('use_first_record')

        // Action 3: lookUpRecord (manager details)
        const lookupManager = actionInstances.find((a: any) => a.comment?.includes('Retrieve sender manager details'))
        expect(lookupManager).toBeDefined()
        const lookupManagerValues = unzipInputArray(lookupManager.values)
        const lookupManagerVar = (name: string) => findInput(lookupManagerValues, name)?.value
        expect(lookupManagerVar('table')).toBe('sys_user')
        expect(lookupManagerVar('sort_type')).toBe('sort_asc')
        expect(lookupManagerVar('if_multiple_records_are_found_action')).toBe('use_first_record')

        // Action 4: createTask (P1 task for manager)
        const createTaskManager = actionInstances.find((a: any) =>
            a.comment?.includes('Create P1 task for sender manager')
        )
        expect(createTaskManager).toBeDefined()
        const createTaskManagerValues = unzipInputArray(createTaskManager.values)
        const createTaskManagerVar = (name: string) => findInput(createTaskManagerValues, name)?.value
        expect(createTaskManagerVar('task_table')).toBe('incident')
        const managerFieldValues = createTaskManagerVar('field_values')
        expect(managerFieldValues).toBeDefined()
        const managerFieldValuesStr = JSON.stringify(managerFieldValues)
        expect(managerFieldValuesStr).toContain('priority=1')
        expect(managerFieldValuesStr).toContain('urgency=1')
        expect(managerFieldValuesStr).toContain('impact=1')

        // Action 5: createTask (P1 task for sender)
        const createTaskSender = actionInstances.find((a: any) => a.comment?.includes('Create P1 task for sender'))
        expect(createTaskSender).toBeDefined()
        const createTaskSenderValues = unzipInputArray(createTaskSender.values)
        const createTaskSenderVar = (name: string) => findInput(createTaskSenderValues, name)?.value
        expect(createTaskSenderVar('task_table')).toBe('incident')
        const senderFieldValues = createTaskSenderVar('field_values')
        expect(senderFieldValues).toBeDefined()
        const senderFieldValuesStr = JSON.stringify(senderFieldValues)
        expect(senderFieldValuesStr).toContain('priority=1')
        expect(senderFieldValuesStr).toContain('urgency=1')
        expect(senderFieldValuesStr).toContain('impact=1')

        // Action 6: createRecord (P3 incident)
        const createIncident = actionInstances.find((a: any) => a.comment?.includes('Create P3 incident from email'))
        expect(createIncident).toBeDefined()
        const createIncidentValues = unzipInputArray(createIncident.values)
        const createIncidentVar = (name: string) => findInput(createIncidentValues, name)?.value
        expect(createIncidentVar('table_name')).toBe('incident')
        const incidentValues = createIncidentVar('values')
        expect(incidentValues).toBeDefined()
        const incidentValuesStr = JSON.stringify(incidentValues)
        expect(incidentValuesStr).toContain('priority=4')
        expect(incidentValuesStr).toContain('urgency=3')
        expect(incidentValuesStr).toContain('impact=3')
        expect(incidentValuesStr).toContain('contact_type=email')

        // Validate flow logic
        const flowLogicInstances = mergedRecords['sys_hub_flow_logic_instance_v2']
        expect(flowLogicInstances.length).toBeGreaterThanOrEqual(2)

        // If logic: Check internal sender and P1
        const ifInternal = flowLogicInstances.find((fl: any) =>
            fl.comment?.includes('Check if internal sender and P1 request')
        )
        expect(ifInternal).toBeDefined()
        const ifInternalValues = unzipInputArray(ifInternal.values)
        const ifInternalData = JSON.stringify(ifInternalValues)
        expect(ifInternalData).toContain('servicenow')
        expect(ifInternalData).toContain('LIKEP1')

        // Else logic
        const elseLogic = flowLogicInstances.find((fl: any) =>
            fl.comment?.includes('Create P3 incident for non-P1 or external requests')
        )
        expect(elseLogic).toBeDefined()
    })
})
